import { useEffect, useState } from 'react'

function App() {
  const [health, setHealth] = useState('')
  useEffect(() => {
    fetch('/api/health').then(r => r.json()).then(d => setHealth(d.status))
  }, [])
  return <div><h1>SaaS App</h1><p>Status: {health}</p></div>
}
export default App
